<?php require_once __DIR__.'/../config/bootstrap.php'; require_client();$pdo=db();$pageTitle='Minhas Encomendas';$st=$pdo->prepare('SELECT * FROM encomendas WHERE cliente_id=? ORDER BY id DESC');$st->execute([current_user()['id']]);$rows=$st->fetchAll();include __DIR__.'/../includes/header.php'; ?><div class="page-head"><h1>Minhas Encomendas</h1><a class="btn primary" href="nova-encomenda.php">＋ Nova encomenda</a></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Número</th><th>Data</th><th>Status</th><th>Total</th><th>Observações</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['numero'])?></td><td><?=datetime_br($r['data_hora'])?></td><td><?=status_badge($r['status'])?></td><td><?=money($r['total'])?></td><td><?=e($r['observacoes'])?></td><td><a class="btn small secondary" href="encomenda.php?id=<?=$r['id']?>">Detalhes</a></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="empty">Nenhuma encomenda encontrada.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
